WITH cleaned AS (SELECT *, temp_c + status_bits temp_c_plus_status_bits FROM device_readings WHERE firmware = '1.1.0'), scored AS (SELECT *, COUNT(status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) status_bits_count_1h, CORR(temp_c, humidity) OVER (PARTITION BY device_code) corr_temp_c_humidity, SUM(temp_c_plus_status_bits) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_temp_c_plus_status_bits, AVG(humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) humidity_avg_1h FROM cleaned WHERE temp_c_plus_status_bits >= 37), metrics AS (SELECT id, temp_c, pressure, firmware, corr_temp_c_humidity, SUM(running_temp_c_plus_status_bits) OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_running_temp_c_plus_status_bits, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts DESC, id) seq_no, LAST_VALUE(humidity_avg_1h) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_humidity_avg_1h, NTILE(3) OVER (ORDER BY pressure, id) pressure_bucket, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY humidity_avg_1h) humidity_avg_1h_dense_rank FROM scored), metrics_device_readings AS (SELECT id, temp_c, pressure, firmware, running_running_temp_c_plus_status_bits, seq_no, DENSE_RANK() OVER (ORDER BY seq_no) seq_no_dense_rank, LAST_VALUE(temp_c, TRUE) OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_temp_c, NTILE(5) OVER (ORDER BY corr_temp_c_humidity, id) corr_temp_c_humidity_bucket FROM metrics) SELECT * FROM (SELECT id, temp_c, last_known_temp_c, pressure FROM metrics_device_readings) src UNPIVOT INCLUDE NULLS (reading FOR metric_name IN (temp_c, last_known_temp_c AS LAST_KNOWN_TEMP_C_VAL, pressure AS PRESSURE)) long_rows
